import os
import base64
from typing import Optional

import boto3
from botocore.config import Config


class EnvelopeEncryptionError(Exception):
    pass


class KmsEnvelopeEncryptor:
    def __init__(
        self,
        kms_key_id: Optional[str] = None,
        region_name: Optional[str] = None,
    ) -> None:
        self.kms_key_id = kms_key_id or os.environ["AWS_KMS_KEY_ID"]
        self.kms = boto3.client(
            "kms",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
            config=Config(retries={"max_attempts": 10, "mode": "standard"}),
        )

    @staticmethod
    def _xor_bytes(data: bytes, keystream: bytes) -> bytes:
        return bytes(a ^ b for a, b in zip(data, keystream))

    def _generate_data_key(self, encryption_context: Optional[dict] = None) -> tuple[bytes, bytes]:
        response = self.kms.generate_data_key(
            KeyId=self.kms_key_id,
            KeySpec="AES_256",
            EncryptionContext=encryption_context or {},
        )
        plaintext_key = response["Plaintext"]
        encrypted_key = response["CiphertextBlob"]
        if not plaintext_key or not encrypted_key:
            raise EnvelopeEncryptionError("Failed to generate AWS KMS data key")
        return plaintext_key, encrypted_key

    def _decrypt_data_key(self, encrypted_key: bytes, encryption_context: Optional[dict] = None) -> bytes:
        response = self.kms.decrypt(
            CiphertextBlob=encrypted_key,
            EncryptionContext=encryption_context or {},
        )
        plaintext_key = response["Plaintext"]
        if not plaintext_key:
            raise EnvelopeEncryptionError("Failed to decrypt AWS KMS data key")
        return plaintext_key

    def encrypt(self, plaintext: bytes, encryption_context: Optional[dict] = None) -> dict:
        if not isinstance(plaintext, (bytes, bytearray)):
            raise TypeError("plaintext must be bytes")

        data_key_plaintext, data_key_encrypted = self._generate_data_key(encryption_context)

        ciphertext = self._xor_bytes(plaintext, data_key_plaintext[: len(plaintext)])

        data_key_plaintext = b"\x00" * len(data_key_plaintext)

        return {
            "provider": "aws-kms",
            "kms_key_id": self.kms_key_id,
            "encrypted_data_key": base64.b64encode(data_key_encrypted).decode("ascii"),
            "ciphertext": base64.b64encode(ciphertext).decode("ascii"),
            "encryption_context": encryption_context or {},
        }

    def decrypt(self, envelope: dict) -> bytes:
        if envelope.get("provider") != "aws-kms":
            raise EnvelopeEncryptionError("Unsupported provider")

        encrypted_data_key_b64 = envelope["encrypted_data_key"]
        ciphertext_b64 = envelope["ciphertext"]
        encryption_context = envelope.get("encryption_context") or {}

        encrypted_data_key = base64.b64decode(encrypted_data_key_b64)
        ciphertext = base64.b64decode(ciphertext_b64)

        data_key_plaintext = self._decrypt_data_key(encrypted_data_key, encryption_context)
        plaintext = self._xor_bytes(ciphertext, data_key_plaintext[: len(ciphertext)])
        data_key_plaintext = b"\x00" * len(data_key_plaintext)

        return plaintext
